-- backfilled from live schema_migrations on 2026-10-24, CI-016
begin;

alter table costing.sku_scheme_viability_snapshot
    add column if not exists marketing_expense_cost_per_sku_ik numeric,
    add column if not exists marketing_expense_cost_per_sku_ok numeric,
    add column if not exists selling_price_bridge_status_ik text,
    add column if not exists selling_price_bridge_status_ok text,
    add column if not exists pricing_bridge_status_ik text,
    add column if not exists pricing_bridge_status_ok text,
    add column if not exists scheme_viability_status_ik text,
    add column if not exists scheme_viability_status_ok text,
    add column if not exists scheme_viability_note_ik text,
    add column if not exists scheme_viability_note_ok text;

do $patch$
declare
    v_oid oid;
    v_def text;
    v_anchor text := E'\n\n    return query';
    v_pos integer;
    v_injection text := E'\n\n    -- Canonical regional Scheme Viability propagation.\n    update costing.sku_scheme_viability_snapshot sv\n    set\n        marketing_expense_cost_per_sku_ik = pb.marketing_expense_cost_per_sku_ik,\n        marketing_expense_cost_per_sku_ok = pb.marketing_expense_cost_per_sku_ok,\n        selling_price_bridge_status_ik = sp.selling_price_bridge_status_ik,\n        selling_price_bridge_status_ok = sp.selling_price_bridge_status_ok,\n        pricing_bridge_status_ik = pb.pricing_bridge_status_ik,\n        pricing_bridge_status_ok = pb.pricing_bridge_status_ok,\n\n        ik_net_sales_realisation = case\n            when sv.ik_scheme_effective_selling_price is not null\n             and sv.ik_contingency_value is not null\n             and pb.marketing_expense_cost_per_sku_ik is not null\n                then sv.ik_scheme_effective_selling_price\n                     - sv.ik_contingency_value\n                     - pb.marketing_expense_cost_per_sku_ik\n            else null::numeric\n        end,\n\n        ok_net_sales_realisation = case\n            when sv.ok_scheme_effective_selling_price is not null\n             and sv.ok_contingency_value is not null\n             and pb.marketing_expense_cost_per_sku_ok is not null\n                then sv.ok_scheme_effective_selling_price\n                     - sv.ok_contingency_value\n                     - pb.marketing_expense_cost_per_sku_ok\n            else null::numeric\n        end,\n\n        ik_margin_amount_after_scheme = case\n            when sv.ik_scheme_effective_selling_price is not null\n             and sv.ik_contingency_value is not null\n             and pb.marketing_expense_cost_per_sku_ik is not null\n             and sv.internal_loaded_cost_per_sku is not null\n                then sv.ik_scheme_effective_selling_price\n                     - sv.ik_contingency_value\n                     - pb.marketing_expense_cost_per_sku_ik\n                     - sv.internal_loaded_cost_per_sku\n            else null::numeric\n        end,\n\n        ok_margin_amount_after_scheme = case\n            when sv.ok_scheme_effective_selling_price is not null\n             and sv.ok_contingency_value is not null\n             and pb.marketing_expense_cost_per_sku_ok is not null\n             and sv.internal_loaded_cost_per_sku is not null\n                then sv.ok_scheme_effective_selling_price\n                     - sv.ok_contingency_value\n                     - pb.marketing_expense_cost_per_sku_ok\n                     - sv.internal_loaded_cost_per_sku\n            else null::numeric\n        end,\n\n        ik_margin_percent_after_scheme = case\n            when (sv.ik_scheme_effective_selling_price\n                  - sv.ik_contingency_value\n                  - pb.marketing_expense_cost_per_sku_ik) > 0\n             and sv.internal_loaded_cost_per_sku is not null\n                then (\n                    sv.ik_scheme_effective_selling_price\n                    - sv.ik_contingency_value\n                    - pb.marketing_expense_cost_per_sku_ik\n                    - sv.internal_loaded_cost_per_sku\n                ) / (\n                    sv.ik_scheme_effective_selling_price\n                    - sv.ik_contingency_value\n                    - pb.marketing_expense_cost_per_sku_ik\n                ) * 100\n            else null::numeric\n        end,\n\n        ok_margin_percent_after_scheme = case\n            when (sv.ok_scheme_effective_selling_price\n                  - sv.ok_contingency_value\n                  - pb.marketing_expense_cost_per_sku_ok) > 0\n             and sv.internal_loaded_cost_per_sku is not null\n                then (\n                    sv.ok_scheme_effective_selling_price\n                    - sv.ok_contingency_value\n                    - pb.marketing_expense_cost_per_sku_ok\n                    - sv.internal_loaded_cost_per_sku\n                ) / (\n                    sv.ok_scheme_effective_selling_price\n                    - sv.ok_contingency_value\n                    - pb.marketing_expense_cost_per_sku_ok\n                ) * 100\n            else null::numeric\n        end,\n\n        scheme_viability_status_ik = case\n            when sp.selling_price_bridge_status_ik = ''BLOCKED'' then ''BLOCKED''\n            when pb.pricing_bridge_status_ik = ''BLOCKED'' then ''BLOCKED''\n            when sv.total_qty <= 0 then ''BLOCKED''\n            when sv.ik_selling_price is null then ''BLOCKED''\n            when sv.ik_contingency_value is null then ''BLOCKED''\n            when pb.marketing_expense_cost_per_sku_ik is null then ''BLOCKED''\n            when sv.internal_loaded_cost_per_sku is null then ''BLOCKED''\n            when sp.selling_price_bridge_status_ik = ''REVIEW_REQUIRED''\n              or pb.pricing_bridge_status_ik = ''REVIEW_REQUIRED'' then ''REVIEW_REQUIRED''\n            else ''READY''\n        end,\n\n        scheme_viability_status_ok = case\n            when sp.selling_price_bridge_status_ok = ''BLOCKED'' then ''BLOCKED''\n            when pb.pricing_bridge_status_ok = ''BLOCKED'' then ''BLOCKED''\n            when sv.total_qty <= 0 then ''BLOCKED''\n            when sv.ok_selling_price is null then ''BLOCKED''\n            when sv.ok_contingency_value is null then ''BLOCKED''\n            when pb.marketing_expense_cost_per_sku_ok is null then ''BLOCKED''\n            when sv.internal_loaded_cost_per_sku is null then ''BLOCKED''\n            when sp.selling_price_bridge_status_ok = ''REVIEW_REQUIRED''\n              or pb.pricing_bridge_status_ok = ''REVIEW_REQUIRED'' then ''REVIEW_REQUIRED''\n            else ''READY''\n        end,\n\n        scheme_viability_note_ik = case\n            when sp.selling_price_bridge_status_ik = ''BLOCKED'' then\n                ''IK Scheme Viability is blocked because the IK Selling Price Bridge is blocked.''\n            when pb.pricing_bridge_status_ik = ''BLOCKED'' then\n                ''IK Scheme Viability is blocked because the IK Pricing Bridge is blocked.''\n            when sv.total_qty <= 0 then\n                ''IK Scheme Viability is blocked because scheme quantity structure is invalid.''\n            when sv.ik_selling_price is null or sv.ik_contingency_value is null then\n                ''IK Scheme Viability is blocked because selling price or contingency is missing.''\n            when pb.marketing_expense_cost_per_sku_ik is null then\n                ''IK Scheme Viability is blocked because regional IK Marketing cost is missing.''\n            when sv.internal_loaded_cost_per_sku is null then\n                ''IK Scheme Viability is blocked because internal loaded cost is missing.''\n            when sp.selling_price_bridge_status_ik = ''REVIEW_REQUIRED''\n              or pb.pricing_bridge_status_ik = ''REVIEW_REQUIRED'' then\n                ''IK Scheme Viability is calculable but requires regional pricing review.''\n            else ''IK Scheme Viability is ready.''\n        end,\n\n        scheme_viability_note_ok = case\n            when sp.selling_price_bridge_status_ok = ''BLOCKED'' then\n                ''OK Scheme Viability is blocked because the OK Selling Price Bridge is blocked.''\n            when pb.pricing_bridge_status_ok = ''BLOCKED'' then\n                ''OK Scheme Viability is blocked because the OK Pricing Bridge is blocked.''\n            when sv.total_qty <= 0 then\n                ''OK Scheme Viability is blocked because scheme quantity structure is invalid.''\n            when sv.ok_selling_price is null or sv.ok_contingency_value is null then\n                ''OK Scheme Viability is blocked because selling price or contingency is missing.''\n            when pb.marketing_expense_cost_per_sku_ok is null then\n                ''OK Scheme Viability is blocked because regional OK Marketing cost is missing.''\n            when sv.internal_loaded_cost_per_sku is null then\n                ''OK Scheme Viability is blocked because internal loaded cost is missing.''\n            when sp.selling_price_bridge_status_ok = ''REVIEW_REQUIRED''\n              or pb.pricing_bridge_status_ok = ''REVIEW_REQUIRED'' then\n                ''OK Scheme Viability is calculable but requires regional pricing review.''\n            else ''OK Scheme Viability is ready.''\n        end,\n\n        scheme_viability_status = case\n            when sp.selling_price_bridge_status_ik = ''BLOCKED''\n              or sp.selling_price_bridge_status_ok = ''BLOCKED''\n              or pb.pricing_bridge_status_ik = ''BLOCKED''\n              or pb.pricing_bridge_status_ok = ''BLOCKED''\n              or sv.total_qty <= 0\n              or sv.ik_selling_price is null\n              or sv.ok_selling_price is null\n              or sv.ik_contingency_value is null\n              or sv.ok_contingency_value is null\n              or pb.marketing_expense_cost_per_sku_ik is null\n              or pb.marketing_expense_cost_per_sku_ok is null\n              or sv.internal_loaded_cost_per_sku is null\n                then ''BLOCKED''\n            when sp.selling_price_bridge_status_ik = ''REVIEW_REQUIRED''\n              or sp.selling_price_bridge_status_ok = ''REVIEW_REQUIRED''\n              or pb.pricing_bridge_status_ik = ''REVIEW_REQUIRED''\n              or pb.pricing_bridge_status_ok = ''REVIEW_REQUIRED''\n                then ''REVIEW_REQUIRED''\n            else ''READY''\n        end,\n\n        scheme_viability_note = case\n            when sp.selling_price_bridge_status_ik = ''BLOCKED''\n              or sp.selling_price_bridge_status_ok = ''BLOCKED''\n              or pb.pricing_bridge_status_ik = ''BLOCKED''\n              or pb.pricing_bridge_status_ok = ''BLOCKED'' then\n                ''Scheme Viability is blocked because at least one regional pricing chain is blocked.''\n            when pb.marketing_expense_cost_per_sku_ik is null\n              or pb.marketing_expense_cost_per_sku_ok is null then\n                ''Scheme Viability is blocked because one or more regional Marketing costs are missing.''\n            when sp.selling_price_bridge_status_ik = ''REVIEW_REQUIRED''\n              or sp.selling_price_bridge_status_ok = ''REVIEW_REQUIRED''\n              or pb.pricing_bridge_status_ik = ''REVIEW_REQUIRED''\n              or pb.pricing_bridge_status_ok = ''REVIEW_REQUIRED'' then\n                ''Scheme Viability is calculable but requires review in at least one region.''\n            else ''Scheme Viability is ready for both IK and OK.''\n        end\n    from costing.sku_selling_price_bridge_snapshot sp\n    join costing.sku_pricing_bridge_snapshot pb\n      on pb.id = sp.pricing_bridge_snapshot_id\n     and pb.refresh_run_id = sp.refresh_run_id\n     and pb.sku_id = sp.sku_id\n    where sv.refresh_run_id = p_refresh_run_id\n      and sp.id = sv.selling_price_bridge_snapshot_id\n      and pb.id = sv.pricing_bridge_snapshot_id;';
begin
    select p.oid, pg_get_functiondef(p.oid)
    into v_oid, v_def
    from pg_proc p
    join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='costing'
      and p.proname='rpc_refresh_sku_scheme_viability_snapshot'
      and pg_get_function_identity_arguments(p.oid)=
          'p_period_start date, p_valuation_date date, p_refresh_run_id bigint';

    if v_oid is null then
        raise exception 'Exact Scheme Viability writer not found.';
    end if;

    if v_def like '%scheme_viability_status_ik = case%' then
        return;
    end if;

    v_pos := strpos(v_def,v_anchor);
    if v_pos=0 then
        raise exception 'Scheme Viability return-query anchor not found.';
    end if;

    v_def := overlay(v_def placing v_injection from v_pos for 0);
    execute v_def;
end;
$patch$;

alter function costing.rpc_refresh_sku_scheme_viability_snapshot(date,date,bigint)
    owner to postgres;

revoke all on function costing.rpc_refresh_sku_scheme_viability_snapshot(date,date,bigint)
    from public, anon, authenticated, service_role;

grant execute on function costing.rpc_refresh_sku_scheme_viability_snapshot(date,date,bigint)
    to postgres;

comment on column costing.sku_scheme_viability_snapshot.marketing_expense_cost_per_sku_ik is
'Canonical IK regional Marketing cost used in IK Scheme Viability net-sales and margin calculations.';
comment on column costing.sku_scheme_viability_snapshot.marketing_expense_cost_per_sku_ok is
'Canonical OK regional Marketing cost used in OK Scheme Viability net-sales and margin calculations.';

commit;